#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

vector<vector<int>> generateMatrix(int n) {
    vector<vector<int>> res(n, vector<int>(n, 0));
    int top = 0, bottom = n - 1;
    int left = 0, right = n - 1;
    int num = 1;
    while (num <= n * n) {
        for (int i = left; i <= right; i++) res[top][i] = num++;
        top++;
        if (num > n * n) break;
        for (int i = top; i <= bottom; i++) res[i][right] = num++;
        right--;
        if (num > n * n) break;
        for (int i = right; i >= left; i--) res[bottom][i] = num++;
        bottom--;
        if (num > n * n) break;
        for (int i = bottom; i >= top; i--) res[i][left] = num++;
        left++;
    }
    return res;
}

int main() {
    int n; if (!(cin >> n)) return 0;
    vector<vector<int>> res = generateMatrix(n);
    cout << "[";
    for (int i = 0; i < n; i++) {
        cout << "[";
        for (int j = 0; j < n; j++) {
            cout << res[i][j] << (j == n - 1 ? "" : ",");
        }
        cout << "]" << (i == n - 1 ? "" : ",");
    }
    cout << "]" << endl;
    return 0;
}

